mapper.select:
WITH metric_tasks AS ( SELECT metric.job_instance_id, SUM(metric.write_row_count) AS inc_records, SUM(metric.write_bytes) AS inc_bytes FROM t_seatunnel_web_job_metrics metric JOIN t_seatunnel_web_job_instance instance ON instance.id = metric.job_instance_id JOIN t_seatunnel_web_job_definition definition ON definition.id = instance.job_definition_id WHERE metric.update_time >= #{startTime} AND metric.update_time <= #{endTime}
GROUP BY metric.job_instance_id ), execution_tasks AS ( SELECT instance.id AS job_instance_id, instance.job_status AS job_status FROM t_seatunnel_web_job_instance instance JOIN t_seatunnel_web_job_definition definition ON definition.id = instance.job_definition_id WHERE COALESCE(instance.start_time, instance.submit_time, instance.create_time) >= #{startTime} AND COALESCE(instance.start_time, instance.submit_time, instance.create_time) <= #{endTime}
UNION ALL SELECT run.id AS job_instance_id, run.status AS job_status FROM t_seatunnel_web_offline_import_task_run run WHERE run.start_time >= #{startTime} AND run.start_time <= #{endTime}
), metric_summary AS ( SELECT COALESCE(SUM(inc_records), 0) AS totalRecords, COALESCE(SUM(inc_bytes), 0) AS totalBytes FROM metric_tasks ), execution_summary AS ( SELECT COUNT(1) AS totalTasks, COALESCE(SUM(CASE WHEN UPPER(job_status) IN ('FINISHED', 'SUCCESS') THEN 1 ELSE 0 END), 0) AS successTasks, COALESCE(SUM(CASE WHEN UPPER(job_status) IN ('FAILED', 'UNKNOWABLE') THEN 1 ELSE 0 END), 0) AS failedTasks, COALESCE(SUM(CASE WHEN UPPER(job_status) IN ('STARTING', 'INITIALIZING', 'CREATED', 'PENDING', 'SCHEDULED', 'RUNNING', 'FAILING', 'DOING_SAVEPOINT', 'CANCELING') THEN 1 ELSE 0 END), 0) AS runningTasks, COALESCE(SUM(CASE WHEN UPPER(job_status) IN ('CANCELED', 'CANCELLED', 'SAVEPOINT_DONE') THEN 1 ELSE 0 END), 0) AS stoppedTasks FROM execution_tasks ), definition_summary AS ( SELECT (SELECT COUNT(1) FROM t_seatunnel_web_job_definition definition WHERE 1 = 1 ) + CASE WHEN #{taskType} IS NULL OR #{taskType} = 'FILE_INGEST' THEN (SELECT COUNT(1) FROM t_seatunnel_web_offline_import_task) ELSE 0 END AS definitionCount ) SELECT metric_summary.totalRecords, metric_summary.totalBytes, execution_summary.totalTasks, execution_summary.successTasks, execution_summary.failedTasks, execution_summary.runningTasks, execution_summary.stoppedTasks, definition_summary.definitionCount FROM metric_summary CROSS JOIN execution_summary CROSS JOIN definition_summary

SELECT x.bucket AS date, COALESCE(SUM(x.inc_records), 0) AS value FROM ( SELECT
AS bucket, metric.job_instance_id, SUM(metric.write_row_count) AS inc_records FROM t_seatunnel_web_job_metrics metric JOIN t_seatunnel_web_job_instance instance ON instance.id = metric.job_instance_id JOIN t_seatunnel_web_job_definition definition ON definition.id = instance.job_definition_id WHERE metric.update_time >= #{startTime} AND metric.update_time <= #{endTime}
GROUP BY bucket, metric.job_instance_id ) x GROUP BY x.bucket ORDER BY x.bucket ASC

SELECT x.bucket AS date, COALESCE(SUM(x.inc_bytes), 0) AS value FROM ( SELECT
AS bucket, metric.job_instance_id, SUM(metric.write_bytes) AS inc_bytes FROM t_seatunnel_web_job_metrics metric JOIN t_seatunnel_web_job_instance instance ON instance.id = metric.job_instance_id JOIN t_seatunnel_web_job_definition definition ON definition.id = instance.job_definition_id WHERE metric.update_time >= #{startTime} AND metric.update_time <= #{endTime}
GROUP BY bucket, metric.job_instance_id ) x GROUP BY x.bucket ORDER BY x.bucket ASC

SELECT
AS date, CAST(AVG(metric.write_qps) AS DECIMAL(20, 4)) AS value FROM t_seatunnel_web_job_metrics metric JOIN t_seatunnel_web_job_instance instance ON instance.id = metric.job_instance_id JOIN t_seatunnel_web_job_definition definition ON definition.id = instance.job_definition_id WHERE metric.update_time >= #{startTime} AND metric.update_time <= #{endTime}
GROUP BY date ORDER BY date ASC

SELECT
AS date, CAST(AVG(metric.write_bps) AS DECIMAL(20, 4)) AS value FROM t_seatunnel_web_job_metrics metric JOIN t_seatunnel_web_job_instance instance ON instance.id = metric.job_instance_id JOIN t_seatunnel_web_job_definition definition ON definition.id = instance.job_definition_id WHERE metric.update_time >= #{startTime} AND metric.update_time <= #{endTime}
GROUP BY date ORDER BY date ASC
